const mongoose = require('mongoose');

const AdminAccountSchema = new mongoose.Schema(
  {
    adminId: {
      type: String,
      required: true,
      unique: true,
      index: true
    }, // e.g., MIT-ADM-001

    username: {
      type: String,
      required: true,
      unique: true,
      trim: true,
      index: true
    },

    // Bcrypt hash (12 rounds). Never selected in standard queries or returned in API responses.
    passwordHash: {
      type: String,
      required: true,
      select: false
    },

    // Optional bcrypt-hashed backup recovery key generated by Admin in Settings
    recoveryKeyHash: {
      type: String,
      default: null,
      select: false
    },

    role: {
      type: String,
      enum: ['SUPER_ADMIN', 'COLLEGE_ADMIN'],
      default: 'SUPER_ADMIN'
    },

    accountStatus: {
      type: String,
      enum: ['ACTIVE', 'LOCKED', 'SUSPENDED'],
      default: 'ACTIVE',
      index: true
    },

    // Incremented whenever username or password changes to invalidate older HTTP-only cookies
    sessionVersion: {
      type: Number,
      required: true,
      default: 1
    },

    // Brute-force protection counters
    failedLoginAttempts: {
      type: Number,
      default: 0
    },
    lockedUntil: {
      type: Date,
      default: null
    },

    lastPasswordUpdateDate: {
      type: Date,
      default: Date.now
    },
    lastSuccessfulLogin: {
      type: Date,
      default: null
    },
    lastLoginIp: {
      type: String,
      default: ''
    }
  },
  {
    timestamps: { createdAt: 'accountCreationDate', updatedAt: 'updatedAt' }
  }
);

// Case-insensitive unique index on username
AdminAccountSchema.index(
  { username: 1 },
  { unique: true, collation: { locale: 'en', strength: 2 } }
);

module.exports = {
  AdminAccount:
    mongoose.models.AdminAccount ||
    mongoose.model('AdminAccount', AdminAccountSchema)
};

